void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec2 st = uv;
    st.x *= iResolution.x/iResolution.y;
    st *= 0.030;
    st -= vec2(1.76,0.007);

    float xx = mix(-0.4, 0.4, 0.5+0.5*sin(iTime));
    st.x += 0.1 * xx;

    vec3 color = vec3(0.);

    float aa = mix(10.544, 10.888, 0.5+0.5*sin(iTime));
    vec2 z = st*aa; //vec2(-0.490,-0.470);
    z *= 0.1;
    int j = 0;
    const int N = 100;
    float rsd = 0.0;
    float ff = mix(1.7, 2.0, 0.5+0.5*sin(0.777*iTime));
    for (int i=0; i<N; i++) {
        //z = vec2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y) + st;
        float snd = mix(abs(z.y), sin(z.y), 0.5+0.5*sin(0.177*iTime));
        z = vec2(abs(z.x), snd);
        z = vec2(z.x*z.x - z.y*z.y, ff*z.x*z.y) + vec2(st.x, -st.y);
        if (z.x*z.x + z.y*z.y > 4.0) {
            rsd = z.x*z.x + z.y*z.y;
            break;
        }
        j++;
    }

    if (j == N) {
        color.r = sin(500.0*length(z));
        color.g = sin(530.0*length(z));
        color.b = sin(570.0*length(z));
    } else {
        float rsdf = -0.056;
        rsd *= rsdf;
        color.r = sin((float(j) - rsd) * 0.11);
        color.g = sin((float(j) - rsd) * 0.13);
        color.b = sin((float(j) - rsd) * 0.17);
        color = pow(color, vec3(6.0));
    }

    fragColor = vec4(color,1.0);
}
